fn is_sorted(a: &[i32]) -> bool {
    // Iterate through the slice, checking each adjacent pair.
    // If we ever find a previous element greater than a later one,
    // it's not sorted in nondecreasing order.
    for i in 1..a.len() {
        if a[i - 1] > a[i] {
            return false;
        }
    }
    true
}

